/* The API. Generated by Chakram. `npm run dev` serves it on PORT (default 3001). */
import { randomUUID } from 'node:crypto';
import { serve } from '@hono/node-server';
import { Hono } from 'hono';
import { cors } from 'hono/cors';
import { logger } from 'hono/logger';
import { z } from 'zod';
import { createStore } from './store.js';
import { currentUser, endSession, hashPassword, startSession, verifyPassword, requireRole, type Vars } from './auth.js';
import { entityRoutes } from './routes.js';
import { seedIfEmpty } from './seed.js';

const store = createStore();
export const app = new Hono<{ Variables: Vars }>();

app.use('*', logger());
app.use('*', async (c, next) => {
  c.header('x-correlation-id', randomUUID());
  await next();
});
app.use('/api/*', cors({ origin: (origin) => origin || '*', credentials: true }));

app.get('/api/health', (c) => c.json({ ok: true }));
app.get('/api/ready', async (c) => {
  try {
    await store.count("Doctor", 'probe');
    return c.json({ ok: true, store: process.env.DATABASE_URL ? 'postgres' : 'memory' });
  } catch (err) {
    return c.json({ ok: false, message: String(err) }, 503);
  }
});

const credentials = z.object({ email: z.email(), password: z.string().min(8).max(200) });
const signup = credentials.extend({ name: z.string().min(1).max(100) });

app.post('/api/auth/signup', async (c) => {
  const parsed = signup.safeParse(await c.req.json().catch(() => null));
  if (!parsed.success) return c.json({ code: 'validation', message: 'Invalid sign-up', retryable: false }, 400);
  if (await store.findUserByEmail(parsed.data.email)) return c.json({ code: 'conflict', message: 'That email is taken', retryable: false }, 409);
  const orgId = process.env.DEFAULT_ORG_ID || 'org-1';
  await store.ensureOrg(orgId, process.env.DEFAULT_ORG_NAME || 'Default');
  // New accounts are members; the seeded owner (see seed.ts) promotes them through PUT /api/auth/users/:id/role.
  const user = await store.createUser({ id: randomUUID(), orgId, email: parsed.data.email, name: parsed.data.name, passwordHash: hashPassword(parsed.data.password), role: 'member' });
  await startSession(c, store, user);
  return c.json({ id: user.id, email: user.email, name: user.name, role: user.role }, 201);
});

app.post('/api/auth/login', async (c) => {
  const parsed = credentials.safeParse(await c.req.json().catch(() => null));
  if (!parsed.success) return c.json({ code: 'validation', message: 'Email and password are required', retryable: false }, 400);
  const user = await store.findUserByEmail(parsed.data.email);
  if (!user || !verifyPassword(parsed.data.password, user.passwordHash)) {
    return c.json({ code: 'unauthenticated', message: 'Wrong email or password', retryable: false }, 401);
  }
  await startSession(c, store, user);
  return c.json({ id: user.id, email: user.email, name: user.name, role: user.role });
});

app.post('/api/auth/logout', async (c) => {
  await endSession(c, store);
  return c.body(null, 204);
});

app.get('/api/auth/me', async (c) => {
  const user = await currentUser(c, store);
  if (!user) return c.json({ code: 'unauthenticated', message: 'Not signed in', retryable: false }, 401);
  return c.json({ id: user.id, email: user.email, name: user.name, role: user.role });
});

app.put('/api/auth/users/:id/role', requireRole(store, 'owner'), async (c) => {
  const parsed = z.object({ role: z.enum(['owner', 'member', 'viewer']) }).safeParse(await c.req.json().catch(() => null));
  if (!parsed.success) return c.json({ code: 'validation', message: 'role must be owner, member or viewer', retryable: false }, 400);
  const target = await store.findUserById(c.req.param('id'));
  if (!target || target.orgId !== c.get('user').orgId) return c.json({ code: 'not_found', message: 'User not found', retryable: false }, 404);
  target.role = parsed.data.role;
  return c.json({ id: target.id, role: target.role });
});

app.route('/api', entityRoutes(store));

app.notFound((c) => c.json({ code: 'not_found', message: 'No such route', retryable: false }, 404));
app.onError((err, c) => {
  console.error(err);
  return c.json({ code: 'internal', message: 'Something went wrong', retryable: true }, 500);
});

const port = Number(process.env.PORT || 3001);
if (process.env.NODE_ENV !== 'test') {
  seedIfEmpty(store).then(() => {
    serve({ fetch: app.fetch, port });
    console.log(`[api] listening on http://localhost:${port}`);
  });
}
